/**
 * BillieWeather design tokens: the single source of truth for every surface.
 *
 * - The Rails website reads them as CSS custom properties from `public/billie-tokens.css`.
 * - The universal React client (macOS, Windows, iOS, Android, browser preview) imports
 *   `packages/design-tokens/dist/tokens.css` and may import this module for SVG charts.
 *
 * Both CSS files are generated by `node packages/design-tokens/scripts/generate.ts` and are
 * checked for drift (and for WCAG contrast) by `packages/design-tokens/test/tokens.test.ts`.
 * Change values here, never in the generated files.
 *
 * Plain TypeScript, no dependencies, no I/O.
 */

export type ThemeName = "light" | "dark";

/** Semantic colors. Every theme defines the same keys. */
export interface ColorTokens {
  /** Page background behind cards. */
  bg: string;
  /** Cards, panels, inputs. */
  surface: string;
  /** Subtle fills: table headers, hovered rows, segmented controls. */
  surfaceMuted: string;
  /** Pressed / selected fill on muted surfaces. */
  surfaceSunken: string;
  /** Dialogs and menus that float above content. */
  surfaceRaised: string;
  border: string;
  borderStrong: string;
  text: string;
  textMuted: string;
  /** Text on accent-strong fills (primary buttons). */
  textOnAccent: string;

  /** Brand pink: indicators, focus, charts. Not for small text on light surfaces. */
  accent: string;
  /** Primary buttons and link text; meets 4.5:1 against surface. */
  accentStrong: string;
  accentHover: string;
  accentSoft: string;
  accentSoftText: string;

  /** Deep purple navigation. */
  sidebar: string;
  sidebarText: string;
  sidebarMuted: string;
  sidebarHover: string;
  sidebarActive: string;
  sidebarBorder: string;

  /** Money in, gains, balanced. `positive` for marks, `positiveText` for figures. */
  positive: string;
  positiveText: string;
  positiveSoft: string;
  /** Money out at risk, deficits, destructive actions. */
  negative: string;
  negativeText: string;
  negativeSoft: string;
  negativeBorder: string;
  /** Needs review, uncertain, stale. */
  warning: string;
  warningText: string;
  warningSoft: string;
  warningBorder: string;
  /** Neutral information, AI-generated content markers. */
  info: string;
  infoText: string;
  infoSoft: string;

  focusRing: string;
  /** Soft halo drawn around focused inputs. */
  focusHalo: string;
  overlay: string;
  /** Translucent fills. Plain rgba so every target engine (Safari 15, Chrome 105) supports them. */
  topbarBg: string;
  accentTint: string;
  accentTintStrong: string;
  positiveBorder: string;
  warningTint: string;

  /** Chart palette. viz0..viz6 follow the spending categories (finance-core spending.ts). */
  viz0: string; viz1: string; viz2: string; viz3: string; viz4: string; viz5: string; viz6: string;
  vizOther: string;
  vizUncategorized: string;
  vizIncome: string;
  vizExpense: string;
  vizGrid: string;
  vizAxis: string;
  vizInk: string;
  vizStrong: string;
}

