const kebab = (key: string) => key.replace(/([a-z])([A-Z0-9])/g, "$1-$2").replace(/([0-9])([a-z])/gi, "$1-$2").toLowerCase();

function colorVars(theme: ThemeName): string[] {
  return Object.entries(color[theme]).map(([key, value]) => `--bw-color-${kebab(key)}: ${value};`);
}

function shadowVars(theme: ThemeName): string[] {
  return Object.entries(shadow[theme]).map(([key, value]) => `--bw-shadow-${key}: ${value};`);
}

function staticVars(): string[] {
  return [
    `--bw-font-family: ${font.family};`,
    `--bw-font-mono: ${font.familyMono};`,
    ...Object.entries(font.size).map(([key, px]) => `--bw-font-size-${key}: ${px}px;`),
    ...Object.entries(font.weight).map(([key, value]) => `--bw-font-weight-${key}: ${value};`),
    ...Object.entries(font.lineHeight).map(([key, value]) => `--bw-line-height-${key}: ${value};`),
    ...Object.entries(space).map(([key, px]) => `--bw-space-${key}: ${px}px;`),
    ...Object.entries(radius).map(([key, px]) => `--bw-radius-${key}: ${px}px;`),
    ...Object.entries(layout).map(([key, px]) => `--bw-${kebab(key)}: ${px}px;`),
    `--bw-motion-fast: ${motion.fast};`,
    `--bw-motion-normal: ${motion.normal};`,
    `--bw-motion-easing: ${motion.easing};`,
  ];
}

const block = (selector: string, lines: string[]) => `${selector} {\n${lines.map((line) => `  ${line}`).join("\n")}\n}`;

/**
 * The generated stylesheet. Theme selection:
 * - default: follows the operating system (`prefers-color-scheme`);
 * - `<html data-theme="light">` or `data-theme="dark"` forces one theme (a per-device preference).
 */
export function renderCss(): string {
  const light = [...colorVars("light"), ...shadowVars("light"), "color-scheme: light;"];
  const dark = [...colorVars("dark"), ...shadowVars("dark"), "color-scheme: dark;"];
  return [
    "/* GENERATED by packages/design-tokens/scripts/generate.ts from packages/design-tokens/src/tokens.ts. Do not edit. */",
    block(":root", [...staticVars(), ...light]),
    `@media (prefers-color-scheme: dark) {\n${block(':root:not([data-theme="light"])', dark).replace(/^/gm, "  ")}\n}`,
    block(':root[data-theme="dark"]', dark),
    "",
  ].join("\n");
}

/** WCAG 2.x relative-luminance contrast ratio between two #RRGGBB colors. */
export function contrastRatio(foreground: string, background: string): number {
  const luminance = (hex: string) => {
    const [r, g, b] = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255).map((v) => (v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4));
    return 0.2126 * r + 0.7152 * g + 0.0722 * b;
  };
  const [a, b] = [luminance(foreground), luminance(background)];
  return (Math.max(a, b) + 0.05) / (Math.min(a, b) + 0.05);
}

/** Text/background pairs the stylesheets rely on, with the minimum contrast each must meet. */
